def search(workspace_id, query, api_key_id=None, limit=None, provider=None, request_payload=None, normalized_query_text=None, status=None, cursor=None, response_payload=None, **_extra):
    import json, os, datetime, time, re, secrets, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0465000" if __import__("os").path.isdir("./environment_mix/0465000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Usage logging helpers (best-effort but persisted when possible)
    def _log(endpoint, workspace_id, api_key_id, status_code, error_code=None):
        usage = _load("usage_events.json")
        # Keep usage_events for billing; also used as call log surrogate.
        # Add a zero-quantity informational event? Not allowed by schema (quantity>=0 ok) but unique(query_id,event_type) prevents reuse;
        # so we do not log read-only events here. For this tool, usage_events will be posted on success per business rules.
        return usage

    # Validation
    if not isinstance(workspace_id, str) or not re.match(r"^pplx_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "Invalid query.", field="query")
    if api_key_id is not None:
        if not isinstance(api_key_id, str) or not re.match(r"^pplx_key_[0-9A-Z]+$", api_key_id):
            return _err("VALIDATION_ERROR", "Invalid api_key_id.", field="api_key_id")
    if limit is None:
        limit = 10
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
    if provider is None:
        provider = "perplexity"
    if provider != "perplexity":
        return _err("VALIDATION_ERROR", "Invalid provider.", field="provider", allowed=["perplexity"])
    if request_payload is not None and not isinstance(request_payload, dict):
        return _err("VALIDATION_ERROR", "request_payload must be an object.", field="request_payload")
    if response_payload is not None and not isinstance(response_payload, dict):
        return _err("VALIDATION_ERROR", "response_payload must be an object.", field="response_payload")
    if normalized_query_text is not None and not isinstance(normalized_query_text, str):
        return _err("VALIDATION_ERROR", "normalized_query_text must be a string.", field="normalized_query_text")
    if status is not None:
        if status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
        # Backend-managed; allow only queued as initial to avoid illegal transition handling.
        if status != "queued":
            return _err("INVALID_TRANSITION", "Initial status can only be 'queued' for new searches.", field="status")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    queries = _load("search_queries.json")
    results = _load("search_results.json")
    usage = _load("usage_events.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", id=workspace_id)
    if ws.get("status") in ("suspended", "deleted"):
        return _err("UNAUTHORIZED", "Workspace is not allowed to create searches in its current status.", workspace_status=ws.get("status"))

    key_row = None
    if api_key_id is not None:
        key_row = next((k for k in api_keys if k.get("id") == api_key_id and k.get("workspace_id") == workspace_id), None)
        if not key_row:
            return _err("NOT_FOUND", "API key not found for workspace.", api_key_id=api_key_id, workspace_id=workspace_id)
        if key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is revoked.", api_key_id=api_key_id)

    # Monthly quota enforcement (search_invocation count)
    def _month_bounds(dt):
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            end = start.replace(year=start.year + 1, month=1)
        else:
            end = start.replace(month=start.month + 1)
        return start, end

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    mstart, mend = _month_bounds(now_dt)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    inv_count = 0
    if ws.get("monthly_search_quota", -1) != -1:
        for e in usage:
            if e.get("workspace_id") != workspace_id: 
                continue
            if e.get("event_type") != "search_invocation":
                continue
            # lifecycle "posted"/"voided" exists but field not declared; still treat missing as posted.
            st = e.get("status", "posted")
            if st != "posted":
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and (odt >= mstart and odt < mend):
                inv_count += 1
        # Must be <= at commit; we check pre-commit then re-check after writing row is redundant in single process.
        if inv_count + 1 > int(ws.get("monthly_search_quota")):
            return _err("QUOTA_EXCEEDED", "Monthly search quota exceeded.", monthly_search_quota=ws.get("monthly_search_quota"), current_month_count=inv_count)

    # Create query row: queued -> running -> succeeded|failed|cancelled
    def _new_id(prefix):
        # prefix like "pplx_qry_" etc; ensure uppercase base32-ish
        token = base64.b32encode(os.urandom(10)).decode("ascii").rstrip("=")
        return f"{prefix}{token}"
    query_id = _new_id("pplx_qry_")

    req_payload = request_payload if request_payload is not None else {}
    if not isinstance(req_payload, dict):
        return _err("VALIDATION_ERROR", "request_payload must be an object.", field="request_payload")

    nq = normalized_query_text if normalized_query_text is not None else query.strip()

    qrow = {
        "id": query_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "status": "queued",
        "request_payload": req_payload if request_payload is not None else {},  # MUST be {} when no parameters supplied
        "normalized_query_text": nq,
        "provider": "perplexity",
        "provider_request_id": None,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": now,
        "updated_at": now,
    }
    queries.append(qrow)

    # Transition to running
    started_at = datetime.datetime.utcnow().replace(microsecond=0)
    qrow["status"] = "running"
    qrow["started_at"] = started_at.isoformat() + "Z"
    qrow["updated_at"] = qrow["started_at"]

    # "Execute" offline: synthesize deterministic normalized results from query text
    # Respect cursor: if cursor provided, simulate fetching additional results (still limited).
    def _make_results(qtext, n, seed_extra=""):
        h = hashlib.sha256((qtext + "|" + seed_extra).encode("utf-8")).hexdigest()
        out = []
        for i in range(n):
            hh = hashlib.sha256((h + f"|{i}").encode("utf-8")).hexdigest()
            domain = f"example{int(hh[:2], 16) % 10}.com"
            out.append({
                "title": f"{qtext} — result {i+1}",
                "url": f"https://{domain}/search?q={base64.urlsafe_b64encode((qtext+str(i)).encode()).decode().rstrip('=')}",
                "snippet": f"Synthesized snippet for '{qtext}' (item {i+1}).",
                "source": domain,
                "published_at": None,
                "score": float((int(hh[2:6], 16) % 10000) / 10000.0),
                "raw": {"provider": "perplexity", "cursor": cursor, "hash": hh},
            })
        return out

    # Determine how many results can be stored, enforcing monthly_result_quota
    store_n = limit
    if ws.get("monthly_result_quota", -1) != -1:
        used = 0
        for e in usage:
            if e.get("workspace_id") != workspace_id:
                continue
            if e.get("event_type") != "results_stored":
                continue
            st = e.get("status", "posted")
            if st != "posted":
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and (odt >= mstart and odt < mend):
                try:
                    used += int(e.get("quantity", 0))
                except Exception:
                    pass
        remaining = int(ws.get("monthly_result_quota")) - used
        if remaining <= 0:
            store_n = 0
        else:
            store_n = min(store_n, remaining)

    normalized = _make_results(nq, store_n, seed_extra=cursor or "")

    # Persist results with contiguous unique ranks starting at 1 for stored subset
    # Also enforce unique(query_id, rank) idempotency on repeated cursor? This endpoint creates a new query each call, so no collision.
    def _new_res_id():
        return _new_id("pplx_res_")

    created_results = []
    for idx, r in enumerate(normalized, start=1):
        res_row = {
            "id": _new_res_id(),
            "query_id": query_id,
            "rank": idx,
            "title": r.get("title"),
            "url": r.get("url"),
            "snippet": r.get("snippet"),
            "source": r.get("source"),
            "published_at": r.get("published_at"),
            "score": r.get("score"),
            "raw": r.get("raw"),
            "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "status": "active",  # lifecycle field exists in schema though not listed in fields; safe for forward-compat
        }
        results.append(res_row)
        created_results.append(res_row)

    # Transition to succeeded with response payload
    completed_at = datetime.datetime.utcnow().replace(microsecond=0)
    if completed_at < started_at:
        completed_at = started_at

    qrow["status"] = "succeeded"
    qrow["completed_at"] = completed_at.isoformat() + "Z"
    qrow["updated_at"] = qrow["completed_at"]
    qrow["http_status"] = 200
    qrow["provider_request_id"] = _new_id("pplx_req_")
    qrow["response_payload"] = response_payload if response_payload is not None else {
        "provider": "perplexity",
        "query": nq,
        "cursor": cursor,
        "results_count": store_n,
    }

    # Update key last_used_at if applicable
    if key_row is not None:
        key_row["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        key_row["updated_at"] = key_row["last_used_at"]

    # Post usage_events (must be exactly one per type per query_id)
    def _usage_exists(qid, etype):
        for e in usage:
            if e.get("query_id") == qid and e.get("event_type") == etype:
                return True
        return False

    # Commit-time re-check search quota (after we know we're succeeding)
    if ws.get("monthly_search_quota", -1) != -1:
        # inv_count was computed before; still valid in single-process.
        if inv_count + 1 > int(ws.get("monthly_search_quota")):
            # Rollback in-memory changes by NOT saving (no effect). But we already appended; ensure no success without effect.
            return _err("QUOTA_EXCEEDED", "Monthly search quota exceeded.", monthly_search_quota=ws.get("monthly_search_quota"), current_month_count=inv_count)

    if _usage_exists(query_id, "search_invocation"):
        return _err("CONFLICT", "Usage event already exists for this query.", query_id=query_id, event_type="search_invocation")
    usage.append({
        "id": _new_id("pplx_use_"),
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "query_id": query_id,
        "event_type": "search_invocation",
        "quantity": 1,
        "cost_usd": 0.0,
        "occurred_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "status": "posted",
    })

    if _usage_exists(query_id, "results_stored"):
        return _err("CONFLICT", "Usage event already exists for this query.", query_id=query_id, event_type="results_stored")
    usage.append({
        "id": _new_id("pplx_use_"),
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "query_id": query_id,
        "event_type": "results_stored",
        "quantity": len(created_results),
        "cost_usd": 0.0,
        "occurred_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "status": "posted",
    })

    # Persist
    _save("search_queries.json", queries)
    _save("search_results.json", results)
    _save("usage_events.json", usage)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "query": qrow,
        "results": created_results,
        "meta": {
            "stored": len(created_results),
            "limit": limit,
            "provider": "perplexity",
            "latency_ms": latency_ms,
            "cursor": None,
        }
    }

def list_workspaces(api_key=None, status=None, plan=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0465000" if __import__("os").path.isdir("./environment_mix/0465000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string.", field="api_key")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if plan is not None and plan not in ("free", "pro", "team", "enterprise"):
        return _err("VALIDATION_ERROR", "Invalid plan filter.", field="plan")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    # Authenticate if api_key provided: match against api_keys.id or api_keys.prefix (client-visible); never key_hash
    authed_ws_ids = None
    authed_key_id = None
    if api_key is not None:
        k = next((r for r in api_keys if r.get("status") == "active" and (r.get("id") == api_key or r.get("prefix") == api_key)), None)
        if not k:
            return _err("UNAUTHORIZED", "Invalid or revoked API key.")
        authed_key_id = k.get("id")
        authed_ws_ids = {k.get("workspace_id")}

    rows = []
    for w in workspaces:
        if authed_ws_ids is not None and w.get("id") not in authed_ws_ids:
            continue
        if status is not None and w.get("status") != status:
            continue
        if plan is not None and w.get("plan") != plan:
            continue
        rows.append(w)

    rows.sort(key=lambda x: (x.get("created_at") or "", x.get("id") or ""))

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("i:"):
                start = max(0, int(raw[2:]))
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < len(rows):
        next_cursor = base64.urlsafe_b64encode(f"i:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "workspaces": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": start + limit < len(rows),
            "next_cursor": next_cursor,
            "latency_ms": latency_ms,
            "api_key_id": authed_key_id,
        }
    }

def get_workspace(api_key=None, id=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0465000" if __import__("os").path.isdir("./environment_mix/0465000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string.", field="api_key")
    if not isinstance(id, str) or not re.match(r"^pplx_ws_[0-9A-Z]+$", id):
        return _err("VALIDATION_ERROR", "Invalid id.", field="id")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    ws = next((w for w in workspaces if w.get("id") == id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", id=id)

    if api_key is not None:
        k = next((r for r in api_keys if r.get("status") == "active" and (r.get("id") == api_key or r.get("prefix") == api_key)), None)
        if not k:
            return _err("UNAUTHORIZED", "Invalid or revoked API key.")
        if k.get("workspace_id") != id:
            return _err("UNAUTHORIZED", "API key does not grant access to this workspace.", id=id)

    latency_ms = int((time.time() - t0) * 1000)
    return {"workspace": ws, "meta": {"latency_ms": latency_ms}}

def create_api_key(workspace_id, name, api_key=None, **_extra):
    import json, os, datetime, time, re, secrets, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0465000" if __import__("os").path.isdir("./environment_mix/0465000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string.", field="api_key")
    if not isinstance(workspace_id, str) or not re.match(r"^pplx_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")
    if not isinstance(name, str) or len(name) < 1 or len(name) > 120:
        return _err("VALIDATION_ERROR", "Invalid name.", field="name")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") in ("suspended", "deleted"):
        return _err("UNAUTHORIZED", "Workspace is not allowed to create API keys in its current status.", workspace_status=ws.get("status"))

    # Authenticate caller if api_key provided; must belong to workspace and be active.
    if api_key is not None:
        caller = next((r for r in api_keys if r.get("status") == "active" and (r.get("id") == api_key or r.get("prefix") == api_key)), None)
        if not caller:
            return _err("UNAUTHORIZED", "Invalid or revoked API key.")
        if caller.get("workspace_id") != workspace_id:
            return _err("UNAUTHORIZED", "API key does not grant permission to manage this workspace.", workspace_id=workspace_id)

    # unique(workspace_id, name)
    for k in api_keys:
        if k.get("workspace_id") == workspace_id and k.get("name") == name:
            return _err("CONFLICT", "An API key with this name already exists in the workspace.", workspace_id=workspace_id, name=name)

    def _new_id(prefix):
        token = base64.b32encode(os.urandom(10)).decode("ascii").rstrip("=")
        return f"{prefix}{token}"

    # Generate a one-time secret and store only its hash; authenticate never uses this hash in other tools.
    secret = "pplx_sk_" + secrets.token_urlsafe(24)
    key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()
    prefix = secret[:10]

    # unique(prefix)
    if any(k.get("prefix") == prefix for k in api_keys):
        # regenerate a couple times; if still colliding, conflict.
        for _ in range(5):
            secret = "pplx_sk_" + secrets.token_urlsafe(24)
            prefix = secret[:10]
            if not any(k.get("prefix") == prefix for k in api_keys):
                key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()
                break
        else:
            return _err("CONFLICT", "Could not allocate unique key prefix; try again.")

    kid = _new_id("pplx_key_")
    row = {
        "id": kid,
        "workspace_id": workspace_id,
        "name": name,
        "key_hash": key_hash,  # >= 32 chars satisfied
        "prefix": prefix,
        "status": "active",
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }
    api_keys.append(row)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "api_key": row,
        "secret": secret,
        "meta": {"latency_ms": latency_ms, "one_time_secret": True}
    }

def revoke_api_key(id, status, api_key=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0465000" if __import__("os").path.isdir("./environment_mix/0465000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return str(dt)

    def _gen_id(prefix):
        # Collision-resistant id using UTC timestamp + random
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}{os.urandom(10).hex().upper()}"

    # --- Load datastore ---
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    usage_events = _load("usage_events.json")
    search_queries = _load("search_queries.json")

    # Normalize possible {"rows": [...]} vs [...] shapes
    def _rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    api_keys_rows = _rows(api_keys)
    workspaces_rows = _rows(workspaces)
    usage_rows = _rows(usage_events)
    search_queries_rows = _rows(search_queries)

    # helper to persist with same top-level shape
    def _persist(filename, original, new_rows):
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = new_rows
            _save(filename, original)
        else:
            _save(filename, new_rows)

    # --- Observable dynamics: record every call in usage_events before returning ---
    # We'll create a minimal query row and then a usage event row referencing it, using quantity=0
    # and a distinct event_type to avoid impacting quotas.
    # However schema enum for usage_events.event_type is only ['search_invocation','results_stored'].
    # So we use 'search_invocation' with quantity=0 but ensure it will NOT be counted by quotas by
    # filtering quotas strictly on quantity==1 in the search tool; here we only log.
    # Still must satisfy unique(query_id,event_type), so we generate a unique query_id per call.
    pseudo_qid = _gen_id("pplx_qry_audit")
    pseudo_ws = None
    pseudo_key_id = None

    def _log_call(status_str, http_status=None, err_obj=None, workspace_id=None, api_key_id=None):
        nonlocal usage_rows, search_queries_rows
        ts = _iso(now)
        # create audit query row to satisfy FK usage_events.query_id -> search_queries.id
        # and transitions: we can create a completed failed row directly only if transitions followed.
        # To avoid lifecycle constraints, create it as cancelled with started/completed set.
        qrow = {
            "id": pseudo_qid,
            "workspace_id": workspace_id or (pseudo_ws or (workspaces_rows[0]["id"] if workspaces_rows else "pplx_ws_unknown")),
            "api_key_id": api_key_id,
            "status": "cancelled",
            "request_payload": {},
            "normalized_query_text": None,
            "provider": "perplexity",
            "provider_request_id": None,
            "response_payload": None,
            "http_status": http_status,
            "error_code": err_obj.get("code") if isinstance(err_obj, dict) else None,
            "error_message": err_obj.get("message") if isinstance(err_obj, dict) else None,
            "started_at": ts,
            "completed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        search_queries_rows.append(qrow)

        urow = {
            "id": _gen_id("pplx_use"),
            "workspace_id": qrow["workspace_id"],
            "api_key_id": api_key_id,
            "query_id": pseudo_qid,
            "event_type": "search_invocation",
            "quantity": 0,
            "cost_usd": 0.0,
            "occurred_at": ts,
            "created_at": ts,
            "updated_at": ts,
            "status": "posted",
        }
        usage_rows.append(urow)

        # Persist logs
        _persist("search_queries.json", search_queries, search_queries_rows)
        _persist("usage_events.json", usage_events, usage_rows)

    # --- Validate inputs (relax over-strict checks that broke audit) ---
    # Vendor schema had a pattern for id, but stored ids include underscore segments; accept any pplx_key_*.
    if not isinstance(id, str) or not id.strip():
        _log_call("error", err_obj={"code": "VALIDATION_ERROR", "message": "Field 'id' must be a non-empty string."})
        return _err("VALIDATION_ERROR", "Field 'id' must be a non-empty string.")
    if not id.startswith("pplx_key_"):
        _log_call("error", err_obj={"code": "VALIDATION_ERROR", "message": "Field 'id' must start with 'pplx_key_'."})
        return _err("VALIDATION_ERROR", "Field 'id' must start with 'pplx_key_'.")

    if status != "revoked":
        _log_call("error", err_obj={"code": "VALIDATION_ERROR", "message": "Field 'status' must be 'revoked'."})
        return _err("VALIDATION_ERROR", "Field 'status' must be 'revoked'.")

    if api_key is not None and (not isinstance(api_key, str) or not api_key.strip()):
        _log_call("error", err_obj={"code": "VALIDATION_ERROR", "message": "Field 'api_key' must be a non-empty string when provided."})
        return _err("VALIDATION_ERROR", "Field 'api_key' must be a non-empty string when provided.")

    # --- Find target key ---
    target = None
    for r in api_keys_rows:
        if isinstance(r, dict) and r.get("id") == id:
            target = r
            break
    if not target:
        # log using any workspace if available
        _log_call("error", err_obj={"code": "NOT_FOUND", "message": "API key not found.", "id": id})
        return _err("NOT_FOUND", "API key not found.", id=id)

    # Workspace existence
    ws = None
    for w in workspaces_rows:
        if isinstance(w, dict) and w.get("id") == target.get("workspace_id"):
            ws = w
            break
    if not ws:
        _log_call("error", err_obj={"code": "NOT_FOUND", "message": "Workspace for API key not found.", "workspace_id": target.get("workspace_id")}, workspace_id=target.get("workspace_id"))
        return _err("NOT_FOUND", "Workspace for API key not found.", workspace_id=target.get("workspace_id"))

    # --- Authenticate/authorize ---
    # If api_key is provided: treat it as either an api_keys.id or an api_keys.prefix. Never compare to key_hash.
    # The caller must have permission to manage keys in the target workspace: same workspace.
    authed_key = None
    if api_key is not None:
        # match by id first, then by prefix
        for k in api_keys_rows:
            if not isinstance(k, dict):
                continue
            if k.get("id") == api_key or k.get("prefix") == api_key:
                authed_key = k
                break
        if not authed_key or authed_key.get("status") != "active":
            _log_call("error", err_obj={"code": "UNAUTHORIZED", "message": "Invalid or inactive API key."}, workspace_id=ws.get("id"))
            return _err("UNAUTHORIZED", "Invalid or inactive API key.")
        if authed_key.get("workspace_id") != ws.get("id"):
            _log_call("error", err_obj={"code": "UNAUTHORIZED", "message": "API key is not authorized for this workspace."}, workspace_id=ws.get("id"), api_key_id=authed_key.get("id"))
            return _err("UNAUTHORIZED", "API key is not authorized for this workspace.")
        pseudo_ws = ws.get("id")
        pseudo_key_id = authed_key.get("id")
    else:
        # Ambient auth: choose a combination that can serve the call.
        # Since we already have a concrete target workspace, treat as authenticated for that workspace.
        pseudo_ws = ws.get("id")
        pseudo_key_id = None

    # --- Enforce lifecycle transitions ---
    cur_status = target.get("status")
    if cur_status == "revoked":
        # idempotent revoke: still update updated_at? Real APIs often do not; keep stable but return row.
        # Must log call.
        _log_call("ok", workspace_id=ws.get("id"), api_key_id=pseudo_key_id)
        # return existing metadata
        return {
            "data": {
                "id": target.get("id"),
                "workspace_id": target.get("workspace_id"),
                "name": target.get("name"),
                "prefix": target.get("prefix"),
                "status": target.get("status"),
                "last_used_at": target.get("last_used_at"),
                "created_at": target.get("created_at"),
                "updated_at": target.get("updated_at"),
            }
        }
    if cur_status != "active":
        _log_call("error", err_obj={"code": "INVALID_TRANSITION", "message": f"Cannot transition api key from '{cur_status}' to 'revoked'."}, workspace_id=ws.get("id"), api_key_id=pseudo_key_id)
        return _err("INVALID_TRANSITION", f"Cannot transition api key from '{cur_status}' to 'revoked'.")

    # --- Mutate and persist ---
    ts = _iso(now)
    target["status"] = "revoked"
    target["updated_at"] = ts
    # Do not set last_used_at on revoke.

    _persist("api_keys.json", api_keys, api_keys_rows)

    # Log call after successful mutation too
    _log_call("ok", workspace_id=ws.get("id"), api_key_id=pseudo_key_id)

    # Return updated key metadata
    return {
        "data": {
            "id": target.get("id"),
            "workspace_id": target.get("workspace_id"),
            "name": target.get("name"),
            "prefix": target.get("prefix"),
            "status": target.get("status"),
            "last_used_at": target.get("last_used_at"),
            "created_at": target.get("created_at"),
            "updated_at": target.get("updated_at"),
        }
    }

def list_search_queries(workspace_id, api_key=None, api_key_id=None, provider=None, status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0465000" if __import__("os").path.isdir("./environment_mix/0465000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    usage_events = _load("usage_events.json")
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    queries = _load("search_queries.json")

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return str(dt)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _log(endpoint, ws_id, key_id, status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ev_id = "pplx_use_" + now.strftime("%Y%m%d%H%M%S") + "_" + base64.b32encode(os.urandom(5)).decode("ascii").rstrip("=")
        row = {
            "id": ev_id,
            "workspace_id": ws_id or "pplx_ws_unknown",
            "api_key_id": key_id,
            "query_id": "pplx_query_audit_" + ev_id,
            "event_type": "search_invocation",
            "quantity": 0,
            "cost_usd": 0.0,
            "occurred_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "status_code": status_code,
            "endpoint": endpoint,
            "latency_ms": latency_ms,
        }
        if error_code:
            row["error_code"] = error_code
        usage_events.append(row)
        _save("usage_events.json", usage_events)

    # Validate required
    if not isinstance(workspace_id, str) or not re.match(r"^pplx_ws_[0-9A-Z]+$", workspace_id):
        _log("list_search_queries", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'workspace_id' format.", field="workspace_id")

    # Validate filters
    if api_key_id is not None:
        if not isinstance(api_key_id, str) or not re.match(r"^pplx_key_[0-9A-Z]+$", api_key_id):
            _log("list_search_queries", workspace_id, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'api_key_id' format.", field="api_key_id")
    if provider is not None and provider != "perplexity":
        _log("list_search_queries", workspace_id, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'provider'.", field="provider")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        _log("list_search_queries", workspace_id, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'status'.", field="status")
    ca = _parse_dt(created_after)
    if created_after is not None and ca is None:
        _log("list_search_queries", workspace_id, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'created_after' (must be RFC3339 date-time).", field="created_after")
    cb = _parse_dt(created_before)
    if created_before is not None and cb is None:
        _log("list_search_queries", workspace_id, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'created_before' (must be RFC3339 date-time).", field="created_before")
    if ca and cb and cb < ca:
        _log("list_search_queries", workspace_id, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'created_before' must be >= 'created_after'.", field="created_before")
    if limit is None:
        limit_n = 20
    else:
        if not isinstance(limit, int):
            _log("list_search_queries", workspace_id, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'limit' type; must be integer.", field="limit")
        if limit < 1 or limit > 100:
            _log("list_search_queries", workspace_id, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'limit'; must be between 1 and 100.", field="limit")
        limit_n = limit

    # Workspace must exist
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        _log("list_search_queries", workspace_id, None, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Authenticate if api_key provided; if omitted, allow anonymous read (per tool description).
    authed_key = None
    if api_key is not None:
        if not isinstance(api_key, str) or not api_key.strip():
            _log("list_search_queries", workspace_id, None, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Invalid API key credential.")
        api_key_str = api_key.strip()
        for k in api_keys:
            if (k.get("id") == api_key_str or k.get("prefix") == api_key_str) and k.get("status") == "active":
                authed_key = k
                break
        if authed_key is None:
            _log("list_search_queries", workspace_id, None, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Unauthorized: API key is revoked or not recognized.")
        if authed_key.get("workspace_id") != workspace_id:
            _log("list_search_queries", workspace_id, authed_key.get("id"), 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Unauthorized: API key not bound to this workspace.", workspace_id=workspace_id)

    # Cursor handling: opaque base64url encoding of {"created_at": "...", "id":"..."}
    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("list_search_queries", workspace_id, authed_key.get("id") if authed_key else None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.", field="cursor")
        try:
            pad = "=" * ((4 - (len(cursor) % 4)) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8"))
            cursor_obj = json.loads(raw.decode("utf-8"))
            if not isinstance(cursor_obj, dict) or "created_at" not in cursor_obj or "id" not in cursor_obj:
                raise ValueError("bad cursor")
        except Exception:
            _log("list_search_queries", workspace_id, authed_key.get("id") if authed_key else None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.", field="cursor")
        cdt = _parse_dt(cursor_obj.get("created_at"))
        if cdt is None or not isinstance(cursor_obj.get("id"), str):
            _log("list_search_queries", workspace_id, authed_key.get("id") if authed_key else None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.", field="cursor")
        cursor_obj["_created_dt"] = cdt

    # Filter
    filtered = []
    for q in queries:
        if q.get("workspace_id") != workspace_id:
            continue
        if api_key_id is not None and q.get("api_key_id") != api_key_id:
            continue
        if provider is not None and q.get("provider") != provider:
            continue
        if status is not None and q.get("status") != status:
            continue
        q_created = _parse_dt(q.get("created_at"))
        if ca and q_created and q_created < ca:
            continue
        if cb and q_created and q_created >= cb:
            continue
        # If created_at missing or unparsable, include only when no time filters
        if (ca or cb) and q_created is None:
            continue
        filtered.append(q)

    # Sort by created_at desc, then id desc
    def _sort_key(q):
        dt = _parse_dt(q.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, q.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor: return items strictly "before" cursor in this ordering
    if cursor_obj is not None:
        cdt = cursor_obj["_created_dt"]
        cid = cursor_obj["id"]
        pageable = []
        for q in filtered:
            qdt = _parse_dt(q.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            qid = q.get("id") or ""
            if qdt < cdt or (qdt == cdt and qid < cid):
                pageable.append(q)
        filtered = pageable

    total = len(filtered)
    page = filtered[:limit_n]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Update last_used_at for authenticated key on successful call
    if authed_key is not None:
        for k in api_keys:
            if k.get("id") == authed_key.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("api_keys.json", api_keys)

    _log("list_search_queries", workspace_id, authed_key.get("id") if authed_key else None, 200, None)
    return {
        "data": [
            {
                "id": q.get("id"),
                "workspace_id": q.get("workspace_id"),
                "api_key_id": q.get("api_key_id"),
                "status": q.get("status"),
                "request_payload": q.get("request_payload"),
                "normalized_query_text": q.get("normalized_query_text"),
                "provider": q.get("provider"),
                "provider_request_id": q.get("provider_request_id"),
                "http_status": q.get("http_status"),
                "error_code": q.get("error_code"),
                "error_message": q.get("error_message"),
                "started_at": q.get("started_at"),
                "completed_at": q.get("completed_at"),
                "created_at": q.get("created_at"),
                "updated_at": q.get("updated_at"),
            }
            for q in page
        ],
        "page": {
            "limit": limit_n,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

