        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _log(endpoint, ws_id, key_id, status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ev_id = "pplx_use_" + now.strftime("%Y%m%d%H%M%S") + "_" + base64.b32encode(os.urandom(5)).decode("ascii").rstrip("=")
        row = {
            "id": ev_id,
            "workspace_id": ws_id or "pplx_ws_unknown",
            "api_key_id": key_id,
            "query_id": "pplx_query_audit_" + ev_id,
