        if ws is None:
            _log("whoami", authed_key.get("workspace_id"), authed_key.get("id"), 404, "NOT_FOUND")
            return _err("NOT_FOUND", "Workspace not found for API key.", workspace_id=authed_key.get("workspace_id"))

    # Compute current month usage (posted events only)
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    def _in_month(ev):
        dt = _parse_dt(ev.get("occurred_at")) or _parse_dt(ev.get("created_at"))
        return dt is not None and dt >= month_start and dt <= now

    search_invocations = 0
    results_stored = 0
    for ev in usage_events:
        if ev.get("workspace_id") != ws.get("id"):
            continue
        if not _in_month(ev):
            continue
        # usage_events lifecycle isn't explicitly stored in the schema rows; treat presence as posted unless status=="voided"
        if ev.get("status") == "voided":
            continue
        if ev.get("event_type") == "search_invocation":
            search_invocations += int(ev.get("quantity") or 0)
        elif ev.get("event_type") == "results_stored":
            results_stored += int(ev.get("quantity") or 0)

    # Update last_used_at if authenticated
    if authed_key is not None:
        for k in api_keys:
            if k.get("id") == authed_key.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("api_keys.json", api_keys)

    _log("whoami", ws.get("id"), authed_key.get("id") if authed_key else None, 200, None)

    monthly_search_quota = ws.get("monthly_search_quota")
    monthly_result_quota = ws.get("monthly_result_quota")

    return {
        "identity": {
            "type": "api_key" if authed_key is not None else "anonymous",
            "api_key": (
                {
                    "id": authed_key.get("id"),
                    "name": authed_key.get("name"),
                    "prefix": authed_key.get("prefix"),
                    "status": authed_key.get("status"),
                    "workspace_id": authed_key.get("workspace_id"),
                    "last_used_at": authed_key.get("last_used_at"),
                    "created_at": authed_key.get("created_at"),
                    "updated_at": authed_key.get("updated_at"),
                } if authed_key is not None else None
            ),
            "workspace": {
                "id": ws.get("id"),
                "name": ws.get("name"),
                "status": ws.get("status"),
                "plan": ws.get("plan"),
                "created_at": ws.get("created_at"),
                "updated_at": ws.get("updated_at"),
            },
            "scopes": ["search:read", "keys:read", "keys:write"] if authed_key is not None else ["search:read"],
        },
        "usage": {
            "calendar_month_start": _iso(month_start),
            "search_invocations": {
                "used": search_invocations,
                "quota": monthly_search_quota,
                "unlimited": (monthly_search_quota == -1),
            },
            "results_stored": {
                "used": results_stored,
                "quota": monthly_result_quota,
                "unlimited": (monthly_result_quota == -1),
            },
        },
    }
